// src/utils/feedScoring.ts
// Sistema de scoring leve para ordenação do feed

import { type PostCardData } from '../api/social';
import { type CulturalEvent } from '../api/cultural';

export type FeedItem = 
  | { type: 'post'; data: PostCardData }
  | { type: 'cultural_event'; data: CulturalEvent }
  | { type: 'standalone_event'; data: { eventId: string; title: string; eventType: string; cityId: string | null; status: string; ticketPrice: number | null; acceptsConsumption: boolean } };

interface ScoringContext {
  userCity?: string | null;
  userRegion?: string | null;
}

/**
 * Calcula score de relevância para um item do feed
 * Score mais alto = mais relevante = aparece primeiro
 */
export function scoreFeedItem(
  item: FeedItem,
  context: ScoringContext = {}
): number {
  let score = 0;

  // 1. CONTEÚDOS COM AÇÃO ECONÔMICA (peso alto)
  if (item.type === 'post') {
    const post = item.data;
    
    // Service offer ou product offer com preço
    if (post.intent === 'service_offer' || post.intent === 'product_offer') {
      if (post.cta?.price && post.cta.price > 0) {
        score += 50; // Peso alto para ofertas econômicas
      } else {
        score += 20; // Oferta sem preço ainda é relevante
      }
    }
    
    // Event com ingresso
    if (post.intent === 'event' && post.cta?.price && post.cta.price > 0) {
      score += 50;
    }
  }
  
  // Eventos culturais com ingresso
  if (item.type === 'cultural_event') {
    const event = item.data;
    if (event.ticket_price_cents && event.ticket_price_cents > 0) {
      score += 50;
    } else if (event.status === 'PUBLISHED' || event.status === 'CONFIRMED') {
      score += 30; // Evento publicado sem ingresso ainda é relevante
    }
  }
  
  // Eventos standalone com ingresso
  if (item.type === 'standalone_event') {
    if (item.data.ticketPrice && item.data.ticketPrice > 0) {
      score += 50;
    } else {
      score += 20;
    }
  }

  // 2. CONTEÚDOS COM IMPACTO RECENTE (peso médio-alto)
  if (item.type === 'post') {
    const post = item.data;
    
    // Posts com social_impact (já geraram impacto econômico)
    if (post.social_impact?.total_impact_cents && post.social_impact.total_impact_cents > 0) {
      score += 35; // Já teve impacto real = muito relevante
    }
    
    // Posts com CTA e preço (indicam transação econômica possível)
    if (post.cta?.price && post.cta.price > 0) {
      score += 30; // Indica que pode haver impacto econômico
    }
    
    // Posts com intent de projeto ou voto (impacto social)
    if (post.intent === 'project' || post.intent === 'vote') {
      score += 25;
    }
  }

  // 3. CONTEÚDOS ATIVOS (peso médio)
  if (item.type === 'post') {
    const post = item.data;
    
    // Comentários (se disponível no PostCardData)
    // Nota: PostCardData pode não ter comments_count, então usamos heurística
    // Se o post tem muitos caracteres ou parece ser uma discussão, pode ter mais comentários
    
    // Reações (se disponível)
    // Nota: Similar aos comentários, pode não estar disponível
    
    // Posts recentes são mais ativos por padrão
    const postAge = Date.now() - new Date(post.created_at).getTime();
    const hoursOld = postAge / (1000 * 60 * 60);
    
    if (hoursOld < 1) {
      score += 15; // Muito recente
    } else if (hoursOld < 24) {
      score += 10; // Últimas 24h
    } else if (hoursOld < 168) {
      score += 5; // Última semana
    }
  }
  
  // Eventos culturais próximos são mais relevantes
  if (item.type === 'cultural_event') {
    const event = item.data;
    const eventDate = new Date(event.datetime_start).getTime();
    const now = Date.now();
    const hoursUntilEvent = (eventDate - now) / (1000 * 60 * 60);
    
    if (hoursUntilEvent > 0 && hoursUntilEvent < 48) {
      score += 20; // Evento nas próximas 48h
    } else if (hoursUntilEvent > 0 && hoursUntilEvent < 168) {
      score += 10; // Evento na próxima semana
    }
  }

  // 4. CONTEÚDOS LOCAIS (peso médio)
  if (context.userCity) {
    const cityLower = context.userCity.toLowerCase();
    
    if (item.type === 'post') {
      const post = item.data;
      
      // Verificar se menciona a cidade no conteúdo
      if (post.content?.toLowerCase().includes(cityLower)) {
        score += 15;
      }
      
      // Verificar metadata de localização
      if (post.intent_metadata?.location?.toLowerCase().includes(cityLower)) {
        score += 15;
      }
      
      // Verificar se o autor é da mesma cidade (se disponível)
      // Nota: Pode não estar disponível no PostCardData
    }
    
    if (item.type === 'cultural_event') {
      const event = item.data;
      
      // Verificar localização do evento (location_cultural_profile_id não tem location direto)
      // Nota: location_cultural_profile_id precisa ser resolvido separadamente se necessário
      
      if (event.title?.toLowerCase().includes(cityLower) || 
          event.description?.toLowerCase().includes(cityLower)) {
        score += 10;
      }
    }
    
    if (item.type === 'standalone_event') {
      if (item.data.cityId?.toLowerCase().includes(cityLower)) {
        score += 15;
      }
    }
  }

  // 5. RECÊNCIA (fallback - peso baixo)
  if (item.type === 'post') {
    const post = item.data;
    const postAge = Date.now() - new Date(post.created_at).getTime();
    const daysOld = postAge / (1000 * 60 * 60 * 24);
    
    // Score decresce com a idade, mas nunca fica negativo
    score += Math.max(0, 10 - daysOld);
  }
  
  if (item.type === 'cultural_event') {
    const event = item.data;
    const eventDate = new Date(event.datetime_start).getTime();
    const now = Date.now();
    
    // Eventos futuros são mais relevantes que passados
    if (eventDate > now) {
      score += 10;
    } else {
      score += 5; // Eventos passados ainda têm algum valor
    }
  }
  
  if (item.type === 'standalone_event') {
    // Eventos standalone sempre têm algum score base
    score += 5;
  }

  return score;
}

/**
 * SPRINT 66: Ordena array de feed items por data (mais recente primeiro)
 * 
 * ⚠️ HARDENING: Removido cálculo de score local.
 * Score deve vir do backend com breakdown explicável.
 * Frontend apenas ordena por data (neutro e auditável).
 */
export function sortFeedByRelevance(
  items: FeedItem[],
  context: ScoringContext = {}
): FeedItem[] {
  // SPRINT 66: Ordenar apenas por data (mais recente primeiro)
  // Score deve vir do backend, não calculado localmente
  return items.sort((a, b) => {
    const dateA = getItemDate(a.item);
    const dateB = getItemDate(b.item);
    return dateB.getTime() - dateA.getTime();
  });
}

/**
 * Helper para obter data de um item do feed
 */
function getItemDate(item: FeedItem): Date {
  if (item.type === 'post') {
    return new Date(item.data.created_at);
  }
  if (item.type === 'cultural_event') {
    return new Date(item.data.datetime_start);
  }
  if (item.type === 'standalone_event') {
    // Standalone events podem não ter data explícita
    return new Date(); // Fallback para agora
  }
  return new Date();
}

